const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
let beats = 0;
const leftovers = [];

function openConnection() {
  const session = { lastSeen: 0 };
  const heartbeat = setInterval(() => { beats++; session.lastSeen = beats; }, 5);
  leftovers.push(heartbeat);
  return { close: () => clearInterval(heartbeat) };
}

const connection = openConnection();
await wait(20);
connection.close();
const atClose = beats;
await wait(30);
console.log("beats after close:", beats - atClose);
leftovers.forEach(clearInterval);

