function createTtlCache(ttlMs, now) {
  const map = new Map();
  return {
    set(key, value) {
      map.set(key, { value, at: now() });
    },
    get(key) {
      const entry = map.get(key);
      if (!entry) return undefined;
      if (now() - entry.at > ttlMs) {
        map.delete(key);
        return undefined;
      }
      return entry.value;
    },
    get size() {
      return map.size;
    },
  };
}

let clock = 0;
const quotes = createTtlCache(30_000, () => clock);
quotes.set("rice-5kg", 950000);
clock = 10_000;
console.log(quotes.get("rice-5kg"), quotes.size);
clock = 45_000;
console.log(quotes.get("rice-5kg"), quotes.size);
